script.setup:
// @jscad/modeling builds the solids with constructive solid geometry: a sphere
// intersected with a cube, three cylinders cut through it, on a twisted star
// extrusion. Its polygons become a flat-shaded mesh; the cuts follow the controls.
const mod = await ctx.utils.import("https://esm.sh/@jscad/modeling@2.13.0");
const J = mod.default ?? mod;
const { primitives: P, booleans: B, extrusions: E, transforms: T, geometries: G } = J;
const toMesh = (geom) => {
  const pos = [], nor = [];
  for (const poly of G.geom3.toPolygons(geom)) {
    const v = poly.vertices;
    // Flat shading: one normal per polygon (jscad is Z-up; swap to Y-up here).
    const a = v[0], b = v[1], c = v[2];
    const e1 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], e2 = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    let n = [e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0]];
    const l = Math.hypot(...n) || 1; n = [n[0] / l, n[2] / l, -n[1] / l];
    for (let i = 1; i + 1 < v.length; i++) for (const p of [v[0], v[i], v[i + 1]]) { pos.push(p[0], p[2], -p[1]); nor.push(...n); }
  }
  return ctx.utils.createMesh({ positions: new Float32Array(pos), normals: new Float32Array(nor) });
};
const build = (hole, round, cuts) => {
  const t0 = performance.now();
  const core = B.intersect(P.cuboid({ size: [2, 2, 2] }), P.sphere({ radius: round, segments: 48 }));
  const r = hole, h = 3;
  const bores = [
    P.cylinder({ radius: r, height: h, segments: 40 }),
    T.rotateX(Math.PI / 2, P.cylinder({ radius: r, height: h, segments: 40 })),
    T.rotateY(Math.PI / 2, P.cylinder({ radius: r, height: h, segments: 40 })),
  ];
  // Extra notches around the equator.
  for (let i = 0; i < cuts; i++) bores.push(T.rotateZ(i / cuts * Math.PI * 2, T.translate([1.15, 0, 0], P.cuboid({ size: [0.5, 0.18, 2.4] }))));
  const piece = B.subtract(core, ...bores);
  const ms = performance.now() - t0;
  ctx.publish("csg ms", Math.round(ms));
  ctx.publish("polygons", G.geom3.toPolygons(piece).length);
  return toMesh(T.translate([0, 0, 0.2], piece));
};
const star = E.extrudeLinear({ height: 0.45, twistAngle: Math.PI / 7, twistSteps: 8 }, P.star({ vertices: 7, outerRadius: 1.35, innerRadius: 0.9 }));
const base = toMesh(T.translate([0, 0, -2.25], B.subtract(star, P.cylinder({ radius: 0.55, height: 3, segments: 32 }))));
const prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal;
uniform mat4 u_vp, u_model; out vec3 v_n; out vec3 v_w;
void main() { vec4 w = u_model * vec4(a_position, 1.0); v_w = w.xyz; v_n = mat3(u_model) * a_normal; gl_Position = u_vp * w; }`, `#version 300 es
precision highp float; in vec3 v_n; in vec3 v_w; out vec4 outColor; uniform vec3 u_color, u_eye;
void main() {
  vec3 n = normalize(v_n), v = normalize(u_eye - v_w);
  vec3 l1 = normalize(vec3(0.5, 0.9, 0.4)), l2 = normalize(vec3(-0.7, 0.2, -0.5));
  float d = max(dot(n, l1), 0.0), d2 = max(dot(n, l2), 0.0);
  float sp = pow(max(dot(n, normalize(l1 + v)), 0.0), 60.0);
  vec3 c = u_color * (0.08 + 0.85 * d) + vec3(0.3, 0.45, 0.8) * d2 * 0.35 + sp * 0.6;
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`);
Object.assign(ctx.state, { build, base, prog, key: "", piece: null,
  camera: ctx.utils.createOrbitCamera({ distance: 8, theta: 0.6, phi: 1.2, target: [0, -0.4, 0] }) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
// Rebuild the solid only when a shape control changed.
const key = [u.u_hole, u.u_round, u.u_cuts].join();
if (key !== s.key) { s.key = key; s.piece = s.build(u.u_hole, u.u_round, u.u_cuts); }
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const eye = s.camera.getEye();
const vp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 35, 0.1, 50), s.camera.getViewMatrix());
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.05, 0.05, 0.07, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.prog);
const spin = mat4.fromYRotation(ctx.time * u.u_spin);
ctx.utils.setUniforms(s.prog, { u_vp: vp, u_eye: eye, u_model: mat4.multiply(spin, mat4.fromXRotation(Math.sin(ctx.time * 0.4) * 0.25)), u_color: u.u_color });
s.piece.draw();
ctx.utils.setUniforms(s.prog, { u_model: mat4.fromYRotation(-ctx.time * u.u_spin * 0.3), u_color: u.u_base });
s.base.draw();
